INSERT INTO task (id, plan_id, subject, kind, status, priority, note, body, created_at, retired_at, created_by_task, web) VALUES (26, 8, 'Live image dev loop for luv-in-space', 'work', 'done', NULL, '2026-10-14, sly, sly-server.lisp, scripts/sly-client.lisp, scripts/build-sly-client, AGENTS.md, docs/luv-capabilities.md, docs/luv-wishlist.md; decision 8; follow-up task 30', 'Part of `plan 8: walking skeleton`: the live-image dev loop (luv''s Slynk-based `./sly`) for this repo''s system.

